head.script:
scwin.pageSize = 5;

scwin.displayFormatter = function(value) {
    var rowIndex = 0;
    var comp = $p.getComponentById(this.callerId);
    var generator = comp && comp.getGenerator ? comp.getGenerator() : null;

    if (generator && generator.getUserData) {
        rowIndex = generator.getUserData("rowIndex");
    }

    return Number(rowIndex || 0) + 1;
};

scwin.adaptiveFormatter = function(info) {
    var width = info && info.width !== undefined ? info.width : arguments[0];

    if (width < 768) {
        this.addClass("loadMore_mobile");
    } else {
        this.removeClass("loadMore_mobile");
    }
};

scwin.onadaptivechange = function() {
    console.log("onadaptivechange Activate Check");
};

scwin.textFormatter = function(val) {
    return "[" + val + "]";
};

scwin.setTextboxLabel = function(component, value) {
    if (!component) {
        return;
    }

    if (component.setLabel) {
        component.setLabel(value);
    } else if (component.setValue) {
        component.setValue(value);
    }
};

scwin.getViewRowCount = function(result) {
    if (result && typeof result.newRowCount === "number") {
        return result.newRowCount;
    }

    if (civ_test && civ_test.getViewRowCount) {
        return civ_test.getViewRowCount();
    }

    return 0;
};

scwin.updateLoadMoreStatus = function(result) {
    var total = dlt_comp && dlt_comp.getRowCount ? dlt_comp.getRowCount() : 0;
    var viewRowCount = scwin.getViewRowCount(result);

    viewRowCount = Math.min(viewRowCount, total);
    scwin.setTextboxLabel(tbx_loadMoreStatus, "표시 " + viewRowCount + " / 전체 " + total + " (pageSize " + scwin.pageSize + ")");

    if (btn_loadMore && btn_loadMore.setDisabled) {
        btn_loadMore.setDisabled(viewRowCount >= total);
    }
    if (btn_loadMore20 && btn_loadMore20.setDisabled) {
        btn_loadMore20.setDisabled(viewRowCount >= total);
    }
};

scwin.updateLoadMoreStatusSoon = function(result) {
    setTimeout(function() {
        scwin.updateLoadMoreStatus(result);
    }, 0);
};

