scwin.getCurrentRowIndex = function() {
    var total = dlt_comp && dlt_comp.getRowCount ? dlt_comp.getRowCount() : 0;
    var rowIndex = civ_test && typeof civ_test._startRow === "number" ? civ_test._startRow : 0;

    if (total === 0) {
        return -1;
    }

    return Math.min(rowIndex, total - 1);
};

scwin.dlt_comp_oncelldatachange = function(info) {
    console.log("+++ dlt_comp oncelldatachange Activate +++");
    console.log("info : " + info);
};

