scwin.onpageload = function() {
    var css = document.createElement("link");
    css.href = "/spall/cursor/cardView/base.css";
    css.type = "text/css";
    css.rel = "stylesheet";
    document.head.appendChild(css);

    dlt_comp.options.saveRemovedData = false;
    dlt_comp.setJSON(scwin.getSampleData());
    scwin.updateLoadMoreStatusSoon();
};

