scwin.btn_setRowData_onclick = function(e) {
    var idx = scwin.getCurrentRowIndex();

    if (idx < 0) {
        return;
    }

    dlt_comp.setRowData(idx, ["추가민원", "333-3333-1-333333", "setRowData", 2, "처리완료", "2026-07-07 07:07:07", "setData부서", 2], true);
};

scwin.btn_setCellData_onclick = function(e) {
    var row = scwin.getCurrentRowIndex();

    if (row < 0) {
        return;
    }

    dlt_comp.setCellData(row, 0, "setCellData 추가");
};

scwin.btn_removeRanges_onclick = function(e) {
    var start = scwin.getCurrentRowIndex();
    var total = dlt_comp.getRowCount();

    if (start < 0) {
        return;
    }

    dlt_comp.removeRange(start, Math.min(start + 4, total - 1));
    scwin.updateLoadMoreStatusSoon();
};

scwin.btn_removeRows_onclick = function(e) {
    var total = dlt_comp.getRowCount();

    if (total < 2) {
        console.log("removeRows requires at least 2 rows. current: " + total);
        return;
    }

    dlt_comp.removeRows([0, 1]);
    scwin.updateLoadMoreStatusSoon();
};

scwin.btn_loadMore_onclick = function(e) {
    var result = civ_test.loadMore();
    scwin.updateLoadMoreStatus(result);
};

scwin.btn_loadMore20_onclick = function(e) {
    var result = civ_test.loadMore(10);
    scwin.updateLoadMoreStatus(result);
};
